import {Link} from "react-router-dom";
import {BarChart3,CheckCircle2,Clock3,Eye,MessageSquare,PlusCircle,ArrowUpRight,ClipboardList} from "lucide-react";
import {useEffect,useState} from "react";
import {getMyListings,getVendorBookings,getVendorApplications} from "../../api/vendorApi";
export default function VendorDashboard(){const[posts,setPosts]=useState([]),[bookings,setBookings]=useState([]),[apps,setApps]=useState([]);useEffect(()=>{Promise.all([getMyListings(),getVendorBookings(),getVendorApplications()]).then(([p,b,a])=>{setPosts(p.data?.content||p.data?.data||p.data||[]);setBookings(b.data?.data||[]);setApps(a.data?.data||[])}).catch(()=>{})},[]);const published=posts.filter(p=>p.status==="PUBLISHED"||p.approvalStatus==="APPROVED").length;const pending=posts.filter(p=>["PENDING_APPROVAL","SUBMITTED"].includes(p.status)).length;const views=posts.reduce((s,p)=>s+Number(p.views||0),0);const stats=[[BarChart3,"Total listings",posts.length],[CheckCircle2,"Published",published],[Clock3,"Pending approval",pending],[Eye,"Total views",views.toLocaleString("en-IN")]];return <div className="page-shell"><div className="relative overflow-hidden rounded-3xl bg-slate-950 p-6 text-white shadow-xl sm:p-9"><div className="absolute -right-16 -top-24 h-72 w-72 rounded-full bg-indigo-500/20 blur-3xl"/><div className="relative flex flex-col gap-6 lg:flex-row lg:items-end lg:justify-between"><div><p className="eyebrow text-slate-400">VENDOR DASHBOARD</p><h1 className="mt-2 text-3xl font-black sm:text-4xl">Grow your business</h1><p className="mt-3 max-w-2xl text-sm leading-6 text-slate-300">Publish trusted listings, respond to customers and turn marketplace activity into business.</p></div><Link className="inline-flex items-center justify-center gap-2 rounded-xl bg-white px-4 py-2.5 text-sm font-bold text-slate-950" to="/vendor/listings/new"><PlusCircle size={17}/> Create listing</Link></div></div><div className="mt-6 grid gap-4 sm:grid-cols-2 lg:grid-cols-4">{stats.map(([I,l,v])=><div className="card card-hover p-5" key={l}><div className="flex items-center justify-between"><div className="grid h-10 w-10 place-items-center rounded-xl bg-slate-100"><I size={18}/></div><b className="text-2xl">{v}</b></div><p className="mt-4 text-sm font-semibold text-slate-500">{l}</p></div>)}</div><div className="mt-6 grid gap-5 lg:grid-cols-[1.6fr_1fr]"><div className="card p-5 sm:p-6"><div className="mb-5 flex items-center justify-between"><div><p className="eyebrow">CONTENT</p><h2 className="section-title mt-1">Recent listings</h2></div><Link className="text-sm font-bold text-slate-700" to="/vendor/listings">View all <ArrowUpRight size={14} className="inline"/></Link></div><div className="space-y-2">{posts.slice(0,5).map(p=><div key={p.id||p._id} className="flex items-center justify-between gap-3 rounded-xl border border-slate-100 p-3.5"><div className="min-w-0"><p className="truncate font-bold">{p.title}</p><p className="mt-0.5 text-xs text-slate-400">{p.type}</p></div><span className="status-pill bg-slate-100 text-slate-600">{p.status||"DRAFT"}</span></div>)}{!posts.length&&<p className="rounded-xl bg-slate-50 p-8 text-center text-sm text-slate-400">No listings yet.</p>}</div></div><div className="space-y-5"><Link to="/vendor/requests" className="card card-hover block p-5 sm:p-6"><div className="flex items-center justify-between"><div className="grid h-11 w-11 place-items-center rounded-xl bg-indigo-50 text-indigo-700"><ClipboardList size={20}/></div><ArrowUpRight size={17}/></div><h2 className="mt-5 font-black">Customer requests</h2><p className="mt-1 text-sm leading-6 text-slate-500">{bookings.length} bookings/orders · {apps.length} job applications</p></Link><Link to="/vendor/enquiries" className="card card-hover block p-5 sm:p-6"><div className="grid h-11 w-11 place-items-center rounded-xl bg-slate-100"><MessageSquare size={20}/></div><h2 className="mt-5 font-black">Customer enquiries</h2><p className="mt-1 text-sm leading-6 text-slate-500">Respond quickly and keep every lead moving.</p></Link></div></div></div>}
